/// Whether a `MEDIA_POSITION` target is a CHANGE worth evaluating (vs the same
/// retained value re-read on every reconcile): the seek runs only on deltas,
/// mirroring the web client. The very first read is always a change.
fn seek_target_changed(previous: Option<f32>, target: f64) -> bool {
    match previous {
        None => true,
        Some(p) => (f64::from(p) - target).abs() > 0.01,
    }
}
