    // (so the app's play button isn't left stuck on a failed stream).
    let timer_pipeline = pipeline.clone();
    let timer_playbin = playbin.clone();
    let timer_sink = sink;
    let timer_suppress = suppress_until.clone();
    let timer_last = last_reported.clone();
