// Wake callback: drain raw EVENT opcodes from the shared ring and route
            // them into the app's bindings. Re-emission (signal → emitter → ring)
            // happens on the GTK main thread, the only writer. Diagnostics: any
            // exception in this path would silently kill all event handling (JNA
            // swallows it) — log it, plus the drain count, to stderr.
            GtkRendererNative.EventCallback onEvent = () -> {
                long t0 = System.nanoTime();
                try {
                    Memory buf = new Memory((long) MAX_EVENTS * 16);
                    int n = core.drainEvents(handle, buf, MAX_EVENTS);
                    if (n > 0) {
                        byte[] raw = buf.getByteArray(0, n * 16);
                        dispatcher.dispatch(reader.decode(raw));
                    }
                    System.err.printf("[java] onEvent drain=%d (%d ns)%n", n,
                            System.nanoTime() - t0);
                } catch (Throwable t) {
                    System.err.println("[java] EVENT HANDLER THREW:");
                    t.printStackTrace();
                }
            };

