// Lazy web-icon glyph resolution. SSR inlines every rendered icon's <path> in
// the page (first render is fully embedded — no network, no cache dependency).
// The DOM client only needs glyph data when a delta asks for an ICON_NAME that
// the page has not embedded — so instead of shipping the canonical catalog in
// the bundle (it was ~13KB), we resolve lazily:
//   1. JS memo cache (this session),
//   2. an already-embedded <svg class="pathland-icon" data-pathland-icon="…">
//      elsewhere in the page (its inner markup — zero bytes, zero network),
//   3. the renderer-owned `/_pathland/icons/<name>.svg` served by the host from
//      the shared Rust library (pathland_html_icon_svg over the C ABI — the same
//      source SSR inlines from), fetched once, then memoized + HTTP-cached.
// Unknown/extension names and fetch failures resolve to the fallback glyph.

const cache = new Map<string, string>();
const inflight = new Map<string, Promise<string>>();
const current = new WeakMap<Element, string>();

/** The reserved framework root (`/_pathland` by default; relocated via the SSR's `data-pathland-base`). */
function basePath(): string {
  return document.documentElement.dataset.pathlandBase ?? "/_pathland";
}

/** The decorative fallback glyph (a faint circle) — the renderer's web_fallback_svg(). */
export const FALLBACK_SVG = '<circle cx="12" cy="12" r="8"/>';

function embeddedGlyph(name: string): string | undefined {
  for (const svg of document.querySelectorAll("svg.pathland-icon[data-pathland-icon]")) {
