            int o = 4 + 4 * i;
            out[o] = (byte) (bits & 0xFF);
            out[o + 1] = (byte) ((bits >>> 8) & 0xFF);
            out[o + 2] = (byte) ((bits >>> 16) & 0xFF);
            out[o + 3] = (byte) ((bits >>> 24) & 0xFF);
        }
        return out;
    }

