/// A `SIZE_THAT_FITS` slot's local fit wiring: keep the candidate thresholds
    /// fresh and attach (once) a `size-allocate` observer that derives the fit
    /// index locally and reports `FIT_CHANGED` only on transitions (the first
    /// real allocation reports once — spec/PRIMITIVES.md §SizeThatFits).
    fn sync_fit(&mut self, id: u32, node: &HostNode) {
        let Some(widget) = self.widgets.get(&id).cloned() else {
            return;
        };
        let Some(sink) = self.event_sink.clone() else {
            return; // no host sink — nothing to report to
        };
        let thresholds: Vec<f32> = node
            .string_property(property_id::FIT_QUERY)
            .map(|csv| csv.split(',').filter_map(|s| s.parse().ok()).collect())
            .unwrap_or_default();
        let state = self.fit_states.entry(id).or_insert_with(|| {
            let shared = Rc::new(RefCell::new(FitState {
                thresholds: Vec::new(),
                last_index: u32::MAX,
            }));
            let sid = shared.clone();
            let sink = sink.clone();
            widget.connect_size_allocate(move |_, allocation| {
                let mut st = sid.borrow_mut();
                let index = pathland_core::fit::fit_index(&st.thresholds, allocation.width() as f32)
                    as u32;
                if index != st.last_index {
                    st.last_index = index;
                    sink.borrow_mut()(Event::FitChanged {
                        target: id,
                        index: index as f32,
                    });
                }
            });
            shared
        });
        state.borrow_mut().thresholds = thresholds;
    }

