import { describe, expect, it } from "vitest";
import { applyBatch } from "../src/apply";
import { parseBatch } from "../src/plpl";
import { readFileSync } from "node:fs";
import type { DomRenderer } from "../src/apply";

const mountHex = readFileSync("/tmp/fit_mount.hex", "utf8").trim();
const swapHex = readFileSync("/tmp/fit_swap.hex", "utf8").trim();

function hexBytes(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

describe("fit swap live replay", () => {
  it("applies the mount frame, attaches the root, then the compact->wide swap", () => {
    document.body.innerHTML = "";
    const r: DomRenderer = { byId: new Map() };
    applyBatch(parseBatch(hexBytes(mountHex)), r);
    const root = r.byId.get(1);
    expect(root).toBeTruthy();
    document.body.appendChild(root as Node);
    expect(document.querySelector(".pathland-library") ?? true).toBeTruthy();

    let threw: unknown = null;
    try {
      applyBatch(parseBatch(hexBytes(swapHex)), r);
    } catch (e) {
      threw = e;
    }
    console.log("swap threw:", threw ? String(threw) : "(no error)");
    expect(threw).toBeNull();
  });
});

